import csv, collections, statistics
vals = collections.defaultdict(list)
for row in csv.DictReader(open(VALUES_CSV)):
    vals[row['timeseries_id']].append((row['timestamp'], float(row['value'])))
ids={'core':'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8','F302':'bcc5a78f-36a4-55a0-9420-7a80fc9b2deb','F101':'7a9e6dea-7214-57d7-a3ab-6fec741ab22a'}
def stats(name, period):
    s,e = period
    out={}
    for n,i in ids.items():
        hh=collections.defaultdict(list)
        for ts,v in vals[i]:
            if s<=ts<e: hh[int(ts[11:13])].append(v)
        m=[statistics.mean(v) for k,v in sorted(hh.items())][:24]
        m+= [m[-1]]*(24-len(m))
        day=statistics.mean([m[h] for h in range(8,18)])
        night=statistics.mean([m[h] for h in range(21,24)]+[m[h] for h in range(0,3)])
        out[n]=(round(statistics.mean(m),2), round(day-night,2), round(max(m)-min(m),2))
    print(name, out)
stats("PRE (Jan-Jun 2018)",('2018-01-01','2018-07-01'))
stats("POST (Jul-Dec 2018)",('2018-07-01','2018-12-31'))

# hourly delta core-F302 before/after
def hd(a,b,period):
    s,e=period
    A={h:[] for h in range(24)}; B={h:[] for h in range(24)}
    for ts,v in vals[ids[a]]:
        if s<=ts<e: A[int(ts[11:13])].append(v)
    for ts,v in vals[ids[b]]:
        if s<=ts<e: B[int(ts[11:13])].append(v)
    return [round(statistics.mean(A[h])-statistics.mean(B[h]),2) for h in range(24) if A[h] and B[h]]
